"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4: Whisper large-v3-turbo transcripts for the API rivals' situation text (plan 6.1: B2-fast, B2-strong and B3
read turbo transcripts; the local systems keep Whisper-small).

Same speech cuts as scripts/p1v4_feats.py: each unit's audio is rebuilt with the renderer's own mixer (episodes: the
stored full mix), the stored 8 s windows are compared with it (stop above 1 LSB, as there), and every speech segment
is cut at its scripted times and keyed by the sha1 of its int16 samples. Each cut's sha1 must equal the one stored in
the folder's segs.json, and every stored sha1 of the units processed must be transcribed, so turbo and small
transcribe the same audio. Same decoding as Whisper-small there (p1v4_feats.Whisper: fp16, greedy, English, the cut
padded to 30 s, at most 160 new tokens); only the model differs: openai/whisper-large-v3-turbo rev 41f01f3 (the
snapshot v0.3's scripts/p1_asr.py used).
Sets: "dev" = all dev units; "examples" = the train_d00 units of the 48 B2 examples (data/p1v4/runs/b2local/
examples.json), so the API rivals' examples show turbo transcripts as their cases do. Test and replication are not
transcribed here (plan 8.5: only in the single final run).
Writes data/p1v4/feats/<folder>_text_turbo.json (sha1 -> transcript).
usage (repo root, GPU venv): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_asr_turbo.py dev|examples [batch]
       test|replication: only in the single final run (p1v4_data.final_unlocked: freeze.json + P1V4_FINAL_RUN=1)
"""
import hashlib
import json
import os
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_data as D  # noqa: E402
import p1v4_feats as FE  # noqa: E402

TURBO = ("openai/whisper-large-v3-turbo", "41f01f3fe87f28c78e2fbf8b568835947dd65ed9")
EXAMPLES = "data/p1v4/runs/b2local/examples.json"


def main(which, batch=16, workers=8):
    import torch
    D.gpu_guard()
    if which == "dev":
        folder, keep = "dev", None
    elif which in ("test", "replication"):                       # the single final run only (after the freeze)
        if not D.final_unlocked():
            raise SystemExit(f"{which} is sealed until the single final run (plan 8.5)")
        folder, keep = which, None
    elif which == "examples":
        folder = "train_d00"
        keep = {e.split("|")[0] for e in json.load(open(EXAMPLES, encoding="utf-8"))["examples"]}
    elif "_d" in which and which.split("_d")[0] in ("dev", "test", "replication"):     # variant folders (2026-11-20)
        if which.split("_d")[0] != "dev" and not D.final_unlocked():
            raise SystemExit(f"{which} is sealed until the single final run (plan 8.5)")
        folder, keep = which, None
    else:
        raise SystemExit(__doc__)
    rows = D.folder_rows(os.path.join(D.RENDER, folder))
    units, order = {}, []
    for r in rows:
        if keep is not None and r["unit"] not in keep:
            continue
        if r["unit"] not in units:
            units[r["unit"]] = []
            order.append(r["unit"])
        units[r["unit"]].append(r)
    segs = json.load(open(f"{FE.OUT}/{folder}_segs.json"))
    want = {h for u in order for r in units[u] for p in r["points"]
            for h in segs.get(f"{r['unit']}|{r['version']}|{p['k']}", {}).values()}
    print(f"{which}: {len(order)} units, {len(want)} unique speech cuts to transcribe", flush=True)
    ds = FE.UnitAudio([units[u] for u in order], folder.split("_d")[0])
    dl = torch.utils.data.DataLoader(ds, batch_size=None, shuffle=False, num_workers=workers, prefetch_factor=4,
                                     collate_fn=FE.identity, persistent_workers=False)
    wh = FE.Whisper(*TURBO)
    text, pending = {}, {}
    max_diff = 0

    def flush():
        ks = sorted(pending, key=lambda k: len(pending[k]))
        for i in range(0, len(ks), batch):
            b = ks[i:i + batch]
            for k, tr in zip(b, wh([pending[k].astype(np.float32) / 32768.0 for k in b])):
                text[k] = tr
        pending.clear()

    t0 = time.time()
    for n, item in enumerate(dl, 1):
        max_diff = max(max_diff, item["max_diff"])
        if item["max_diff"] > FE.MAX_DIFF_LSB or not item["gain_ok"]:
            raise SystemExit(f"rebuilt audio differs from the stored windows: {item['unit']}")
        for pid, key, cut in item["cuts"]:
            h = hashlib.sha1(cut.tobytes()).hexdigest()
            if segs[pid][key] != h:
                raise SystemExit(f"cut differs from the one transcribed by Whisper-small: {pid} {key}")
            if h not in text and h not in pending:
                pending[h] = cut
        if len(pending) >= 256:
            flush()
        if n % 200 == 0:
            el = time.time() - t0
            print(f"{n}/{len(order)} units, {len(text)} cuts done, {el / 60:.1f} min, "
                  f"eta {el / n * (len(order) - n) / 60:.0f} min", flush=True)
    flush()
    if set(text) != want:
        raise SystemExit(f"transcribed {len(text)} cuts, segs.json has {len(want)}: sets differ")
    out = f"{FE.OUT}/{folder}_text_turbo.json"
    json.dump(text, open(out, "w", encoding="utf-8"), ensure_ascii=False)
    small = json.load(open(f"{FE.OUT}/{folder}_text_small.json", encoding="utf-8"))
    same = np.mean([text[h].lower().strip(" .,!?") == small[h].lower().strip(" .,!?") for h in text])
    print(f"wrote {out}: {len(text)} transcripts in {(time.time() - t0) / 60:.1f} min; max window difference "
          f"{max_diff} LSB; same text as Whisper-small (case and end punctuation ignored) {same:.3f}", flush=True)


if __name__ == "__main__":
    main(sys.argv[1], int(sys.argv[2]) if len(sys.argv) > 2 else 16)
